--
-- Name: purchase_base_budgets; Type: TABLE; Schema: public; Owner: admin
--

CREATE TABLE public.purchase_base_budgets (
    id bigint NOT NULL,
    currency_id integer,
    subtotal double precision,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    date date,
    tax_id bigint,
    orderable_type character varying(255),
    orderable_id bigint,
    prepared_by_id bigint,
    reviewed_by_id bigint,
    verified_by_id bigint,
    first_signature_id bigint,
    second_signature_id bigint,
    status character varying(255) DEFAULT 'WAIT'::character varying NOT NULL,
    send_notify boolean,
    CONSTRAINT purchase_base_budgets_status_check CHECK (((status)::text = ANY (ARRAY[('WAIT'::character varying)::text, ('QUOTED'::character varying)::text, ('PARTIALLY_QUOTED'::character varying)::text, ('WAIT_QUOTATION'::character varying)::text, ('BOUGHT'::character varying)::text])))
);


ALTER TABLE public.purchase_base_budgets OWNER TO admin;

--
-- Name: COLUMN purchase_base_budgets.currency_id; Type: COMMENT; Schema: public; Owner: admin
--

COMMENT ON COLUMN public.purchase_base_budgets.currency_id IS 'Unidad monetaria en la que se expresara el presupuesto base.';


--
-- Name: COLUMN purchase_base_budgets.subtotal; Type: COMMENT; Schema: public; Owner: admin
--

COMMENT ON COLUMN public.purchase_base_budgets.subtotal IS 'Subtotal del registro de presupuesto base';


--
-- Name: COLUMN purchase_base_budgets.deleted_at; Type: COMMENT; Schema: public; Owner: admin
--

COMMENT ON COLUMN public.purchase_base_budgets.deleted_at IS 'Fecha y hora en la que el registro fue eliminado';


--
-- Name: COLUMN purchase_base_budgets.date; Type: COMMENT; Schema: public; Owner: admin
--

COMMENT ON COLUMN public.purchase_base_budgets.date IS 'Fecha del requerimiento';


--
-- Name: COLUMN purchase_base_budgets.status; Type: COMMENT; Schema: public; Owner: admin
--

COMMENT ON COLUMN public.purchase_base_budgets.status IS 'Determina el estatus del presupuesto base
                              (WAIT) - espera por ser completado.
                              (WAIT_QUOTATION) - espera ser cotizado.
                              (PARTIALLY_QUOTED) - Cotizado Parcialmente,
                              (QUOTED) - Cotizado,
                              (BOUGHT) - comprado';


--
-- Name: COLUMN purchase_base_budgets.send_notify; Type: COMMENT; Schema: public; Owner: admin
--

COMMENT ON COLUMN public.purchase_base_budgets.send_notify IS 'Estado del envio de la notificación para solicitar disponibilidad presupuiestaria';


